const payload = $input.first().json;
const ticker = payload.ticker || 'SOL/USDT';
const currentVolume = payload.volume || 45000;
const avgVolume20 = payload.avgVolume || 12000;
const rvol = Math.round((currentVolume / avgVolume20) * 10) / 10;
const squeezeStatus = payload.squeeze || 'FIRED_LONG';

const isBreakout = rvol >= 2.5;

return {
  json: {
    ticker,
    rvol,
    currentVolume,
    squeezeStatus,
    isBreakout,
    action: isBreakout ? 'BUY' : 'HOLD',
    breakoutVelocity: 'HIGH',
    trailingStopAtr: 2.0
  }
};

const prev = $input.first().json;
const text = prev.content || prev.output || JSON.stringify(prev);

return {
  json: {
    success: true,
    botId: 'volume-breakout',
    botName: 'Volume Anomaly & Breakout Hunter',
    alert: 'EXPLOSIVE_VOLUME_EXPANSION',
    momentumAnalysis: text,
    timestamp: new Date().toISOString()
  }
};
